const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readingOrder = ['start','values','representation','selection','loops','functions','arrays','files','design','software-responsibility','networks','addressing','network-design','network-review','consolidation','exam-preparation'];
function lessonPage(ch){const order=ch.unit===4?['unit4-design','unit4-sql','unit4-project','unit4-analysis','unit4-controls','unit4-crypto','unit4-ethics','unit4-review','unit4-consolidation','unit4-exam']:ch.unit===3?['unit3-fluency','unit3-structures','unit3-search','unit3-sort','unit3-objects','unit3-inheritance','unit3-project','unit3-reliability','unit3-network-models','unit3-addressing','unit3-secure-networks','unit3-review','unit3-consolidation','unit3-exam']:ch.unit===2?['database-foundations','entities-relationships','normalisation','sql-basics','database-solution','security-threats','responsible-data','unit2-review','unit2-consolidation','unit2-exam']:readingOrder;const position=order.indexOf(ch.id);return `<article class="lesson"><p class="eyebrow">UNIT ${ch.unit||1} / WEEK ${ch.week} / CHAPTER ${position+1}</p><h1>${ch.title}</h1><p class="lede">${ch.intro}</p><span class="pill">${ch.badge||'PYTHON 3'}</span> <span class="pill">CLASSROOM DRAFT · REVIEW PENDING</span><div class="no-print" style="margin-top:20px"><button id="chapter-print">Print / save as PDF</button> ${ch.code?'<button id="chapter-download">Download example</button>':''}</div><h2>What you’ll learn</h2><div class="objectives"><ul>${ch.objectives.map(x=>`<li>${x}</li>`).join('')}</ul></div>${ch.sections.map(([title,html],i)=>`<section><h2>${i+1}. ${title}</h2>${html}</section>`).join('')}${ch.code?`<h2>Worked Python example</h2><p>Predict the result first, then run and modify the downloaded file in your Python environment.</p><pre><code>${escapeHtml(ch.code)}</code></pre>`:''}<h2>Practise and explain</h2>${ch.practice.map(([type,q,a])=>`<section class="practice"><p class="eyebrow">${type}</p><p>${q}</p><details><summary>Show explained answer</summary><p>${escapeHtml(a)}</p></details></section>`).join('')}<h2>Your practical task</h2><div class="card"><p>${ch.task}</p><details><summary>Show illustrative answer / example</summary>${ch.code?`<pre><code>${escapeHtml(ch.solution)}</code></pre><p>Compare the logic and tests, not just the spelling of variable names.</p>`:`<p>${escapeHtml(ch.solution)}</p>`}</details></div><h2>Check your understanding</h2><p>${ch.quiz.q}</p><div id="chapter-quiz">${ch.quiz.options.map((t,i)=>`<button class="quiz-option" data-choice="${i}">${escapeHtml(t)}</button>`).join(' ')}</div><p id="chapter-feedback" class="feedback" aria-live="polite"></p><h2>Chapter recap</h2><p>${ch.recap}</p><details><summary>Suggested classroom sequence</summary><ol>${ch.lessons.map(x=>`<li>${x}</li>`).join('')}</ol><p>${(ch.unit||1)===1&&ch.week===2?"Week 2 is shared by the values and representation chapters; their activities fit into four total lessons. ":""}This draft chapter provides learning activities and explained answers. It does not establish complete syllabus coverage.</p></details><p class="reference">Technical reference: <a href="${ch.reference}" target="_blank" rel="noopener">${ch.refTitle}</a>. Curriculum requirements: <a href="${source}" target="_blank" rel="noopener">SCSA Computer Science</a>.</p><nav class="chapter-nav no-print">${position>0?`<a href="#${order[position-1]}">← Previous chapter</a>`:'<a href="#contents">← Contents</a>'}${position<order.length-1?`<a href="#${order[position+1]}">Next chapter →</a>`:ch.next?`<a href="${ch.next}">Next planned chapter →</a>`:'<a href="#teaching">View teaching sequence →</a>'}</nav></article>`}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){const route=currentTextbookRoute();const ch=chapters.find(c=>c.id===route);if(ch){document.querySelector('main').innerHTML=lessonPage(ch)+footer;window.scrollTo(0,0);if(ch.code)document.querySelector('#chapter-download').onclick=()=>downloadText(ch.code,`${ch.id}_example.py`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.choice)===ch.quiz.answer;document.querySelector('#chapter-feedback').textContent=(correct?'Correct. ':'Try again. ')+ch.quiz.explanation});document.title=ch.title+' | CS ATAR';}else if(route==='audits'){document.querySelector('main').innerHTML=auditHubPage()+footer;window.scrollTo(0,0);document.title='Coverage & audits | CS ATAR';}else if(route==='unit4-coverage'){document.querySelector('main').innerHTML=unit4CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 4 coverage audit | CS ATAR';}else if(route==='unit3-evidence'){document.querySelector('main').innerHTML=unit3EvidencePage()+footer;window.scrollTo(0,0);document.title='Unit 3 practical evidence | CS ATAR';}else if(route==='unit3-coverage'){document.querySelector('main').innerHTML=unit3CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 3 coverage audit | CS ATAR';}else if(route==='unit2-coverage'){document.querySelector('main').innerHTML=unit2CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 2 coverage audit | CS ATAR';}else if(route==='coverage'){document.querySelector('main').innerHTML=coveragePage()+footer;window.scrollTo(0,0);document.title='Unit 1 coverage audit | CS ATAR';}else if(route==='teaching'){document.querySelector('main').innerHTML=teacherPlannerPage()+footer;window.scrollTo(0,0);document.title='Teaching sequence | CS ATAR';}else{renderLegacy();document.title=(route==='selection'?'Making decisions with selection':route==='glossary'?'Glossary':'Computer Science ATAR')+' | Classroom Textbook';if(route==='selection'){const nav=document.createElement('nav');nav.className='chapter-nav no-print';nav.innerHTML='<a href="#representation">← Previous chapter</a><a href="#loops">Next chapter →</a>';document.querySelector('.lesson').append(nav);}}}
window.addEventListener('hashchange',render);render();
